__d(function(e,t,a,o,i,r,n){i.exports={widgets:{mobileApp:"Mobile App",games:"Games",dataToMusic:"Data to Music",weather:"Weather and Air",waterData:"Water Data",welcome:"Welcome!",aboutUs:"About Us",rightToKnow:"Right to Know",waterReports:"Water Reports",photoGallery:"Photo Gallery",videos:"Videos",credits:"Credits"},feedback:{button:"Feedback",title:"Provide Your Feedback",placeholder:"Enter your feedback here...",success:"Thank you! Your feedback has been saved.",emptyError:"Please enter some feedback before submitting.",cancel:"Cancel",submit:"Submit",noSubmissions:"No feedback submissions yet.",submissions:"Feedback Submissions"},feedbackViewer:{refresh:"Refresh",exportJSON:"Export JSON",exportCSV:"Export CSV",clearAll:"Clear All",close:"Close",confirmDelete:"Are you sure you want to delete all feedback?",emptyFeedback:"No feedback submissions yet."},reachability:{toggle:"Accessibility",description:"Toggle reachability assistance"},language:{Toggle:"Language",Description:"Change language",English:"English",Spanish:"Espa\xf1ol",Albanian:"Shqip",Georgian:"\u10e5\u10d0\u10e0\u10d7\u10e3\u10da\u10d8",Portuguese:"Portugu\xeas",current:"Current Language"},aboutScreen:{missionTitle:"At Seidenberg School, we believe students can make a difference today, before they launch their careers of tomorrow.",safeWater:"Is your water safe to drink?",rightToKnow:"We believe you have the right to know.",theGEC:"the Gale Epstein Center",blueColab:"Blue CoLab",description:"we're working to ensure you have the critical information you need about your water quality. Within our center we have the","descriptionCont.":"a hands-on lab where our dedicated team of students, interns, graduate assistants, faculty, and staff are advancing technology, information, and warning systems to make this a reality.",atPrefix:"At",location:"At our technology lab overlooking the Hudson River, our Choate Pond lab on campus, and our data lab in the Goldstein Academic Center, the Gale Epstein Center is dedicated to the proposition that you have the",rightToKnowBold:"right-to-know",locationEnd:"the quality of your water before you drink it, swim in it, fish it, or even swamp your canoe.",waterContaminationRisks:"Water Contamination Risks",contaminationText1:"Chances are the water you use is safe, but millions have unfortunately found otherwise. In a matter of hours, a single sip of pathogen-contaminated water can result in serious illness. Currently labs require 24 - 48 hours to report analyses of samples taken weekly, or less.",milwaukee:"Milwaukee (1993)",milwaukeeText:"400,000 residents became ill and 100 died after drinking water contaminated with cryptosporidium.",hoosickFalls:"Hoosick Falls",newburghNY:"Newburgh, NY",hoosickText:"For years, residents of Hoosick Falls and Newburgh, NY may have been unknowingly exposed to highly toxic PFAS.",globalProblem:"Water contamination is a global problem, making millions of people ill.",realTime:"Real-time",detection:"technological detection of water contaminants is the best defense.",handsOnApproach:"Gale Epstein Center's Hands-On Approach",threefoldApproach:"With a three-fold approach to water quality testing, Gale Epstein Center merges the power of cutting-edge sensors with real-time data collection and AI-driven analysis\u2014making water contamination easier to detect and faster to report.",teamWorkPrefix:"They work in a",teamWorkBold:"team-based environment",teamWorkSuffix:", using the Gale Epstein Center's dedicated labs, instruments, equipment, and servers.",closingParagraph:"The Gale Epstein Center stands for everything that makes Seidenberg School a special place \u2014 harnessing innovation on behalf of society, and providing students with skill-based experiences that lead to a career meaningful to them, and to society."},waterReports:{title:"Water Quality Reports are updated annually in compliance with EPA regulations.",description:"At Pace University, we are committed to providing transparent information about the quality of our water. Pace itself is known for it's water supply initiatives and sustainability efforts rather than it's role as a water supplier itself. Specifically in the Pleasantville campus it is considered a \"Community Water System\" by the EPA, meaning it serves at least 25 people for at least 60 days a year. Our water is supplied by the Town of Mount Pleasant and is regularly tested to ensure it meets all federal and state water quality standards.",goal:"The goal for all water consumers is to be well-aware of the quality of their water and any potential contaminants that may be present. With the advanced framework brought to you by the Gale Epstein Center, we encourage you to explore our annual water quality reports below to learn more about the safety and quality of the water we provide.",selectYear:"Select a year to view the corresponding Water Quality Report.",pdfFormat:"(Reports are provided in PDF format.)",whereWater:"Where does our water come from?",waterSource:"The Pace University water in Pleasantville is from Ashokan Reservoir in the Catskill Mountains, traveling 91 miles underground aqueducts in order to reach campus. The Croton Reservoir, which is 12 miles away, is our backup source in case of any emergencies or for maintenance activities, dating back to 1842 (by damming the Croton River, making it the first upstate water source). Since we are a federally-recognized water community, Pace is to be responsible for managing their water supply, as well as meeting all the required testing standards.",back:"\u2190 Back"},mobileApp:{heading:"Access our research data and information on the go.",stayUpdated:"Stay updated with real-time data.",download:"Download our mobile app for better access."},rightToKnow:{mainHeading:"Understand Your Right to Know About Water Quality",introText:"Here at the Gale Epstein Center, we focus on the right to know H2O. We hold dear the United Nation's Sustainable Development Goal (SDG) 6 \u2013 ensuring access to clean water and sanitation for all. People should have easy access to clean water. We believe that people need to have the right to know what's in their water in order for them to make informed decisions.",team2023:"2023 Team",team2024:"2024 Team",team2025:"2025 Team",descriptionR2K2023:"Right to Know H2O - 2023",descriptionR2K2024:"Right to Know H2O - 2024",descriptionR2K2025:"Right to Know H2O - 2025",studentsR2K2023:"Left to right, from the top: Cece Porter, Lilah McCormack, Louisa Moquete, Sasha Palmer, Meryl Mizell, Sasha Breygina.",textR2K2023:"The first-ever Right-to-Know H2O team, led by Prof. John Cronin, is advancing SDG 6: Clean Water and Sanitation by promoting a simple principle: access to clean water is a human right\u2014and so is the right to know if your water is safe. The team is developing a UN-focused petition, U.S. policy recommendations, and a Pace-based water information system to make water quality transparency a global standard.",studentsR2K2024:"Left to right, from the top: Ian Shimba, Isabella Coraci, Lizi Imedashvili, Sebastian Roman, Phoenix Ellrodt, Victor Lima, Charles Metayer.",textR2K2024:"The second-ever Right-to-Know H2O team is building on the foundation set by the 2023 cohort, advancing the belief that the human right to safe drinking water must include the right to know if campus water is safe. With over 270 million people relying on water at the world's 25,000+ colleges and universities, the team aims to create a technology-driven model that campuses everywhere can adopt. Their work begins at Pace's Pleasantville campus with a water-quality awareness campaign, a summit with local officials, an online learning hub, and a campus survey. Next, the team is developing a data-collection system, digital reporting tools, and an enhanced emergency alert feature for water issues. Supported by the Millennium Fellowship network, these Seidenberg students are preparing tools that other institutions can use to replicate the model.",studentsR2K2025:"Team members left to right, from the top: Isaac Lasso Younes, Silas Gonzalez; Mamoun Edfouf, Prof Leanne Keeley, Phoenix Ellrodt, Lizi Imedashvilli, Kiley Cosgrove, Prof John Cronin, Dillon Talactac, Caroline Zanuto-Winter, and Noor Huda. Not pictured: Graig Decembre, Nailah Brown, Skyler Flynn.",textR2K2025:"In October 2025, 34 Pace University students were selected\u2014out of over 60,000 global applicants\u2014to join the United Nations Millennium Fellowship, representing a record high for Pace. This year's cohort stands out not only for its size but also for its international reach: for the first time, Pace's Gale Epstein Center partnered with students from Finland's H\xe4me University of Applied Sciences, forming a 19-member team focused on SDG 6: Clean Water and Sanitation. Their goal: to develop a bilateral action plan to promote the \"right to know what's in our water,\" culminating in a joint proposal presented at the United Nations during the Finnish delegation's visit to Pace. This cohort works across over 13 countries, tackling issues from environmental justice to education, health equity, and renewable systems through student-led projects."},games:{playInteractive:"Play interactive games to learn about water!",back:"\u2190 Back",created:"Created by",play:"Play Game",jeopardyDesc:"Learn more about water while having fun.",ccDesc:"The one and only Cronin hops over sharks. Based off of Google Chrome dinosaur game.",sfDesc:"Flappy bird remake."},videos:{watchEducational:"Watch educational videos on water science!"},standby:{currentTime:"Current Time"},weatherWidget:{aqi:"Air Quality Index"},waterReport:{"2024Button":"2024 Water Report (by the Gale Epstein Center)","2024Title":"Annual Water Quality Report for 2024 (by the Gale Epstein Center)","2023Button":"2023 Water Report","2023Title":"Annual Water Quality Report for 2023","2022Button":"2022 Water Report","2022Title":"Annual Water Quality Report for 2022","2021Button":"2021 Water Report","2021Title":"Annual Water Quality Report for 2021","2020Button":"2020 Water Report","2020Title":"Annual Water Quality Report for 2020","2019Button":"2019 Water Report","2019Title":"Annual Water Quality Report for 2019","2018Button":"2018 Water Report","2018Title":"Annual Water Quality Report for 2018","2017Button":"2017 Water Report","2017Title":"Annual Water Quality Report for 2017"}}},831,[]);
__d(function(e,a,o,n,r,s,i){r.exports={widgets:{mobileApp:"Aplicaci\xf3n M\xf3vil",games:"Juegos",dataToMusic:"Datos a M\xfasica",weather:"Clima y Aire",waterData:"Datos del Agua",welcome:"\xa1Bienvenidos!",aboutUs:"Sobre Nosotros",rightToKnow:"Derecho a Saber",waterReports:"Reportes de Agua",photoGallery:"Galer\xeda de Fotos",videos:"Videos",credits:"Cr\xe9ditos"},feedback:{button:"Comentarios",title:"Proporcione Sus Comentarios",placeholder:"Ingrese sus comentarios aqu\xed...",success:"\xa1Gracias! Sus comentarios han sido guardados.",emptyError:"Por favor, ingrese algunos comentarios antes de enviar.",cancel:"Cancelar",submit:"Enviar",noSubmissions:"A\xfan no hay comentarios enviados.",submissions:"Env\xedos de Comentarios"},feedbackViewer:{refresh:"Actualizar",exportJSON:"Exportar JSON",exportCSV:"Exportar CSV",clearAll:"Borrar Todo",close:"Cerrar",confirmDelete:"\xbfEst\xe1 seguro de que desea eliminar todos los comentarios?",emptyFeedback:"A\xfan no hay comentarios enviados."},reachability:{toggle:"Accesibilidad",description:"Alternar asistencia de alcance"},language:{toggle:"Idioma",description:"Cambiar idioma",english:"English",spanish:"Espa\xf1ol",albanian:"Shqip",georgian:"\u10e5\u10d0\u10e0\u10d7\u10e3\u10da\u10d8",portuguese:"Portugu\xeas",current:"Idioma Actual"},aboutScreen:{missionTitle:"En la facultad Seidenberg, creemos que los estudiantes pueden marcar la diferencia hoy, antes de iniciar sus carreras del ma\xf1ana.",safeWater:"\xbfEs seguro beber su agua?",rightToKnow:"Creemos que tiene derecho a saberlo.",theGEC:"el Gale Epstein Center",blueColab:"Blue CoLab",description:"estamos trabajando para garantizar que dispongas de la informaci\xf3n esencial que necesitas sobre la calidad del agua. En nuestro centro contamos con el","descriptionCont.":"un laboratorio pr\xe1ctico en el que nuestro equipo, formado por estudiantes, becarios, ayudantes de posgrado, profesores y personal, trabaja para mejorar la tecnolog\xeda, la informaci\xf3n y los sistemas de alerta con el fin de hacer esto realidad.",atPrefix:"En",location:"En nuestro laboratorio de tecnolog\xeda con vistas al r\xedo Hudson, nuestro laboratorio de la laguna 'Choate' en el campus y nuestro laboratorio de datos en el Centro Acad\xe9mico Goldstein, Gale Epstein Center est\xe1 dedicado a la misi\xf3n de que usted tiene el",rightToKnowBold:"derecho a saber",locationEnd:"la calidad de su agua antes de beberla, nadar, pescar o incluso undir tu canoa.",waterContaminationRisks:"Riesgos de Contaminaci\xf3n del Agua",contaminationText1:"Es probable que el agua que usa sea segura, pero millones desafortunadamente han encontrado lo contrario. En cuesti\xf3n de horas, un sorbo de agua contaminada con pat\xf3genos puede resultar en una enfermedad grave. Actualmente los laboratorios requieren 24-48 horas para reportar an\xe1lisis de muestras tomadas semanalmente, o menos.",milwaukee:"Milwaukee (1993)",milwaukeeText:"400,000 residentes enfermaron y 100 murieron despu\xe9s de beber agua contaminada con cryptosporidium.",hoosickFalls:"Hoosick Falls",newburghNY:"Newburgh, NY",hoosickText:"Durante a\xf1os, los residentes de Hoosick Falls y Newburgh, NY pueden haber estado expuestos sin saberlo a PFAS altamente t\xf3xicos.",globalProblem:"La contaminaci\xf3n del agua es un problema global que enferma a millones de personas.",realTime:"En tiempo real",detection:"la detecci\xf3n tecnol\xf3gica de contaminantes del agua es la mejor defensa.",handsOnApproach:"Enfoque Pr\xe1ctico de Gale Epstein Center",threefoldApproach:"Con un enfoque triple para las pruebas de calidad del agua, Gale Epstein Center combina el poder de sensores de vanguardia con la recopilaci\xf3n de datos en tiempo real y an\xe1lisis impulsado por IA, lo que hace que la contaminaci\xf3n del agua sea m\xe1s f\xe1cil de detectar y m\xe1s r\xe1pida de reportar.",teamWorkPrefix:"Trabajan en un",teamWorkBold:"entorno basado en equipo",teamWorkSuffix:", utilizando los laboratorios, instrumentos, equipos y servidores dedicados de Gale Epstein Center.",closingParagraph:"Gale Epstein Center representa todo lo que hace que la facultad Seidenberg sea un lugar especial: aprovechar la innovaci\xf3n en beneficio de la sociedad y brindar a los estudiantes experiencias basadas en habilidades que conduzcan a una carrera significativa para ellos y para la sociedad."},waterReports:{title:"Los Reportes de Calidad del Agua se actualizan anualmente en cumplimiento con las regulaciones de la EPA.",description:"En la Universidad Pace, nos comprometemos a proporcionar informaci\xf3n transparente sobre la calidad de nuestra agua. Pace es conocida por sus iniciativas de suministro de agua y esfuerzos de sostenibilidad en lugar de su papel como proveedor de agua. Espec\xedficamente en el campus de Pleasantville, se considera un \"Sistema de Agua Comunitario\" por la EPA, lo que significa que sirve a al menos 25 personas durante al menos 60 d\xedas al a\xf1o. Nuestro agua es suministrada por la Municipalidad de Mount Pleasant y se prueba regularmente para asegurar que cumple con todos los est\xe1ndares federales y estatales de calidad del agua.",goal:"El objetivo para todos los consumidores de agua es estar bien informados sobre la calidad de su agua y cualquier contaminante potencial que pueda estar presente. Con el marco avanzado que le proporciona Gale Epstein Center, le recomendamos que explore nuestros informes anuales de calidad del agua a continuaci\xf3n para obtener m\xe1s informaci\xf3n sobre la seguridad y la calidad del agua que proporcionamos.",selectYear:"Seleccione un a\xf1o para ver el Informe de Calidad del Agua correspondiente.",pdfFormat:"(Los informes se proporcionan en formato PDF.)",whereWater:"\xbfDe d\xf3nde viene nuestra agua?",waterSource:"El agua de la Universidad Pace en Pleasantville proviene del Embalse de Ashokan en las Monta\xf1as Catskill, viajando 91 millas a trav\xe9s de acueductos subterr\xe1neos para llegar al campus. El Embalse de Croton, que est\xe1 a 12 millas de distancia, es nuestra fuente de respaldo en caso de emergencias o para actividades de mantenimiento, que se remonta a 1842 (al represar el r\xedo Croton, lo que lo convierte en la primera fuente de agua upstate). Dado que somos una comunidad de agua reconocida federalmente, Pace es responsable de gestionar su suministro de agua, as\xed como de cumplir con todos los est\xe1ndares de prueba requeridos.",back:"\u2190 Atr\xe1s"},mobileApp:{heading:"Accede a nuestros datos de investigaci\xf3n e informaci\xf3n sobre la marcha.",stayUpdated:"Mant\xe9ngase actualizado con datos en tiempo real.",download:"Descarga nuestra aplicaci\xf3n m\xf3vil para un mejor acceso."},rightToKnow:{mainHeading:"Comprenda Su Derecho a Saber Sobre la Calidad del Agua",introText:"Aqu\xed en Gale Epstein Center, nos enfocamos en el derecho a saber H2O. Valoramos el Objetivo de Desarrollo Sostenible (ODS) 6 de las Naciones Unidas: garantizar el acceso a agua limpia y saneamiento para todos. Las personas deben tener f\xe1cil acceso a agua limpia. Creemos que las personas necesitan tener el derecho a saber qu\xe9 hay en su agua para poder tomar decisiones informadas.",team2023:"Equipo 2023",team2024:"Equipo 2024",team2025:"Equipo 2025",descriptionR2K2023:"Derecho a Saber H2O - 2023",descriptionR2K2024:"Derecho a Saber H2O - 2024",descriptionR2K2025:"Derecho a Saber H2O - 2025",studentsR2K2023:"De izquierda a derecha, desde arriba: Cece Porter, Lilah McCormack, Louisa Moquete, Sasha Palmer, Meryl Mizell, Sasha Breygina.",textR2K2023:"El primer equipo de Derecho a Saber H2O, dirigido por el Prof. John Cronin, est\xe1 avanzando el ODS 6: Agua Limpia y Saneamiento al promover un principio simple: el acceso a agua limpia es un derecho humano, al igual que el derecho a saber si su agua es segura. El equipo est\xe1 desarrollando una petici\xf3n enfocada en la ONU, recomendaciones de pol\xedtica estadounidense y un sistema de informaci\xf3n de agua basado en Pace para hacer que la transparencia de la calidad del agua sea un est\xe1ndar global.",studentsR2K2024:"De izquierda a derecha, desde arriba: Ian Shimba, Isabella Coraci, Lizi Imedashvili, Sebastian Roman, Phoenix Ellrodt, Victor Lima, Charles Metayer.",textR2K2024:"El segundo equipo de Derecho a Saber H2O se basa en equipo anterior de 2023, avanzando la creencia de que el derecho humano al agua potable segura debe incluir el derecho a saber si el agua del campus es segura. Con m\xe1s de 270 millones de personas dependiendo del agua en las m\xe1s de 25,000 universidades y colegios del mundo, el equipo apunta a crear un modelo impulsado por la tecnolog\xeda que los campus puedan adoptar. Su trabajo comienza en el campus de Pleasantville de Pace con una campa\xf1a de conciencia sobre la calidad del agua, una cumbre con funcionarios locales, un centro de aprendizaje en l\xednea y una encuesta del campus. A continuaci\xf3n, el equipo est\xe1 desarrollando un sistema de recopilaci\xf3n de datos, herramientas de informes digitales y una funci\xf3n mejorada de alerta de emergencia para problemas de agua. Apoyados por la red del Grupo del Milenio, estos estudiantes de Seidenberg est\xe1n preparando herramientas que otras instituciones pueden usar para replicar el modelo.",studentsR2K2025:"Miembros del equipo de izquierda a derecha, desde arriba: Isaac Lasso Younes, Silas Gonzalez; Mamoun Edfouf, Prof Leanne Keeley, Phoenix Ellrodt, Lizi Imedashvilli, Kiley Cosgrove, Prof John Cronin, Dillon Talactac, Caroline Zanuto-Winter y Noor Huda. No aparece: Graig Decembre, Nailah Brown, Skyler Flynn.",textR2K2025:"En octubre de 2025, 34 estudiantes de la Universidad de Pace fueron seleccionados de m\xe1s de 60,000 solicitantes globales para unirse a la Fellowship del Milenio de las Naciones Unidas, representando un r\xe9cord para Pace. El grupo de este a\xf1o se destaca no solo por su tama\xf1o sino tambi\xe9n por su alcance internacional: por primera vez, Gale Epstein Center de Pace se asoci\xf3 con estudiantes de la Universidad de Ciencias Aplicadas H\xe4me de Finlandia, formando un equipo de 19 miembros enfocado en el ODS 6: Agua Limpia y Saneamiento. Su objetivo: desarrollar un plan de acci\xf3n bilateral para promover el \"derecho a saber qu\xe9 hay en nuestra agua\", culminando en una propuesta conjunta presentada en las Naciones Unidas durante la visita de la delegaci\xf3n finlandesa a Pace. Esta grupo de trabaja representa a m\xe1s de 13 pa\xedses, abordando problemas de justicia ambiental a educaci\xf3n, equidad de salud y sistemas renovables a trav\xe9s de proyectos dirigidos por estudiantes."},games:{playInteractive:"\xa1Juega juegos interactivos para aprender sobre el agua!",back:"\u2190 Atr\xe1s",created:"Creado por",play:"\xa1Jugar!",jeopardyDesc:"Aprende m\xe1s sobre el agua mientras te diviertes.",ccDesc:"El \xfanico e inigualable Cronin salta sobre tiburones. Basado en el juego del dinosaurio de Google Chrome.",sfDesc:"Remake de Flappy Bird."},videos:{watchEducational:"Mira videos educativos sobre la ciencia del agua."},standby:{currentTime:"Hora Actual"},weatherWidget:{aqi:"\xcdndice de Calidad del Aire"},waterReport:{"2024Button":"Informe de Agua 2024 (por Gale Epstein Center)","2024Title":"Informe Anual de Calidad del Agua 2024 (por Gale Epstein Center)","2023Button":"Informe de Agua 2023","2023Title":"Informe Anual de Calidad del Agua 2023","2022Button":"Informe de Agua 2022","2022Title":"Informe Anual de Calidad del Agua 2022","2021Button":"Informe de Agua 2021","2021Title":"Informe Anual de Calidad del Agua 2021","2020Button":"Informe de Agua 2020","2020Title":"Informe Anual de Calidad del Agua 2020","2019Button":"Informe de Agua 2019","2019Title":"Informe Anual de Calidad del Agua 2019","2018Button":"Informe de Agua 2018","2018Title":"Informe Anual de Calidad del Agua 2018","2017Button":"Informe de Agua 2017","2017Title":"Informe Anual de Calidad del Agua 2017"}}},832,[]);
